A('1964-0510-vimytex', '1964-05-10', VH, 'Saigon. Saigon sends Civil Guard and paratroopers against the Vimytex strikers, May 10.', 'III, 355', place='saigon', also=['vietnam'], check='the history\'s count of the dead is cut off at III, 355.')
